logs.mkdir(parents=True,exist_ok=True,mode=0o700)
os.chown(logs,0,0); os.chmod(logs,0o700)
logst=logs.lstat()
if not logs.is_dir() or logs.is_symlink() or logst.st_uid!=0 or (logst.st_mode&0o777)!=0o700: print("ENV_INVALID: LOGS must be root-owned mode 0700",file=sys.stderr); raise SystemExit(2)
